#[cfg(feature = "validate")]
#[test]
fn rejects_invalid_examples() {
    use trust_tasks_rs::validate::ValidatedPayload;
    let fixtures: &[(&str, &str)] = &[
        (
            "Missing required `subject` — a certificate request names who is to be certified, and a custodian that defaulted one would be choosing the name on the producer's behalf.",
            "{\n  \"keyId\": \"eudi-access-p256\"\n}",
        ),
        (
            "Empty `subject` — an empty distinguished name would make the subject alternative name the only identity, which RFC 5280 handles with a critical extension this task never requests.",
            "{\n  \"keyId\": \"eudi-access-p256\",\n  \"subject\": []\n}",
        ),
        (
            "`subject` as a DN string — the custodian never parses a distinguished name; the structured attribute list is what lets it encode exactly what was asked.",
            "{\n  \"keyId\": \"eudi-access-p256\",\n  \"subject\": \"CN=Example Community Verifier,O=Example Community e.V.,C=DE\"\n}",
        ),
        (
            "An attribute type outside the closed set (passing an OID through) — each type's encoding is fixed by the specification, so an unknown one cannot be encoded on trust.",
            "{\n  \"keyId\": \"eudi-access-p256\",\n  \"subject\": [\n    {\n      \"type\": \"2.5.4.12\",\n      \"value\": \"Verifier\"\n    }\n  ]\n}",
        ),
        (
            "A lower-cased attribute short name — these are externally owned names carried verbatim (`CN`, not `cn`).",
            "{\n  \"keyId\": \"eudi-access-p256\",\n  \"subject\": [\n    {\n      \"type\": \"cn\",\n      \"value\": \"Example Community Verifier\"\n    }\n  ]\n}",
        ),
        (
            "An attribute with an empty value — X.520 attribute values are never empty.",
            "{\n  \"keyId\": \"eudi-access-p256\",\n  \"subject\": [\n    {\n      \"type\": \"CN\",\n      \"value\": \"\"\n    }\n  ]\n}",
        ),
        (
            "A multi-valued RDN smuggled as an extra member — each element is one single-valued RDN.",
            "{\n  \"keyId\": \"eudi-access-p256\",\n  \"subject\": [\n    {\n      \"also\": {\n        \"type\": \"O\",\n        \"value\": \"Example Community e.V.\"\n      },\n      \"type\": \"CN\",\n      \"value\": \"Example Community Verifier\"\n    }\n  ]\n}",
        ),
        (
            "A raw DER CertificationRequestInfo to sign — the generic oracle's shape. additionalProperties: false is what keeps the custodian building the request itself.",
            "{\n  \"certificationRequestInfo\": \"MIIBNgIBADB4MQswCQYDVQQGEwJERQ\",\n  \"keyId\": \"eudi-access-p256\",\n  \"subject\": [\n    {\n      \"type\": \"CN\",\n      \"value\": \"Example Community Verifier\"\n    }\n  ]\n}",
        ),
        (
            "A requested extension — extensions come from the CA, and only the subject alternative name is ever requested.",
            "{\n  \"extensions\": [\n    {\n      \"critical\": true,\n      \"oid\": \"2.5.29.19\",\n      \"value\": \"MAMBAf8\"\n    }\n  ],\n  \"keyId\": \"eudi-access-p256\",\n  \"subject\": [\n    {\n      \"type\": \"CN\",\n      \"value\": \"Example Community Verifier\"\n    }\n  ]\n}",
        ),
        (
            "A wildcard dNSName — this task requests exact host names only.",
            "{\n  \"keyId\": \"eudi-access-p256\",\n  \"subject\": [\n    {\n      \"type\": \"CN\",\n      \"value\": \"Example Community Verifier\"\n    }\n  ],\n  \"subjectAltNames\": {\n    \"dns\": [\n      \"*.community.example\"\n    ]\n  }\n}",
        ),
        (
            "An unknown subjectAltNames kind (`ip`) — the set of kinds is closed.",
            "{\n  \"keyId\": \"eudi-access-p256\",\n  \"subject\": [\n    {\n      \"type\": \"CN\",\n      \"value\": \"Example Community Verifier\"\n    }\n  ],\n  \"subjectAltNames\": {\n    \"ip\": [\n      \"192.0.2.1\"\n    ]\n  }\n}",
        ),
        (
            "An empty `subjectAltNames` object — present means at least one name; absent means none.",
            "{\n  \"keyId\": \"eudi-access-p256\",\n  \"subject\": [\n    {\n      \"type\": \"CN\",\n      \"value\": \"Example Community Verifier\"\n    }\n  ],\n  \"subjectAltNames\": {}\n}",
        ),
        (
            "A URI with a space — uniformResourceIdentifier entries are printable ASCII without spaces.",
            "{\n  \"keyId\": \"eudi-access-p256\",\n  \"subject\": [\n    {\n      \"type\": \"CN\",\n      \"value\": \"Example Community Verifier\"\n    }\n  ],\n  \"subjectAltNames\": {\n    \"uri\": [\n      \"https://verifier.community.example/a path\"\n    ]\n  }\n}",
        ),
        (
            "Bare/unnamespaced ext key — SPEC §4.5.1 producer rule.",
            "{\n  \"ext\": {\n    \"no-dots\": {}\n  },\n  \"keyId\": \"eudi-access-p256\",\n  \"subject\": [\n    {\n      \"type\": \"CN\",\n      \"value\": \"Example Community Verifier\"\n    }\n  ]\n}",
        ),
    ];
    for (i, (note, raw)) in fixtures.iter().enumerate() {
        let value: serde_json::Value = match serde_json::from_str(raw) {
            Ok(v) => v,
            Err(_) => continue,
        };
        let serde_ok = serde_json::from_value::<spec::Payload>(value.clone()).is_ok();
        let schema_ok = spec::Payload::validate_value(&value).is_ok();
        assert!(
            !(serde_ok && schema_ok),
            "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
            i + 1,
            note,
            raw
        );
    }
}
